import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { 
  User, Edit, LogOut, 
  Trophy, Zap, Flame, BookOpen, Award, Globe 
} from "lucide-react";
import "../App.css"; // Ensure styles are loaded

const Profile = () => {
  const navigate = useNavigate();
  
  // 1. State to hold User Data
  const [userData, setUserData] = useState({
    name: "Student",
    email: "student@school.edu",
    grade: "Grade 10",
    xp: 402,
    streak: 0,
    quizzes: 9,
    avgScore: "76%"
  });

  // 2. Load Real Data from LocalStorage on Component Mount
  useEffect(() => {
    // Try to get stored user info (assumes you saved it during Login)
    const storedName = localStorage.getItem("userName");
    const storedEmail = localStorage.getItem("userEmail");
    
    if (storedName) {
      setUserData(prev => ({
        ...prev,
        name: storedName,
        email: storedEmail || "no-email@provided.com"
      }));
    }
  }, []);

  // 3. Handle Sign Out
  const handleSignOut = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("userName");
    localStorage.removeItem("userEmail");
    navigate("/login"); // Redirect to Login
  };

  return (
    <div className="profile-page-container">
      {/* --- Navbar (Matches Screenshot) --- */}
      <nav className="navbar profile-nav">
        <div className="logo" onClick={() => navigate("/")} style={{cursor:'pointer'}}>
          <div className="logo-icon-box"><Globe size={24} color="white" /></div>
          <span className="logo-text">VidyaQuest</span>
        </div>
        <div className="nav-links">
          <span onClick={() => navigate("/")}>Home</span>
          <span>Subjects</span>
          <span>Games</span>
          <span className="active-link">Leaderboard</span>
        </div>
        <div className="profile-actions">
           <button className="lang-btn">🌐 English</button>
           <button className="user-pill">
              <User size={16} /> {userData.name}
           </button>
        </div>
      </nav>

      <div className="profile-content">
        
        {/* --- Header Card (Banner + Avatar) --- */}
        <div className="profile-header-card">
          <div className="profile-banner"></div>
          
          <div className="profile-info-row">
            {/* Avatar Box */}
            <div className="profile-avatar-box">
              <User size={64} color="#10b981" />
            </div>

            {/* Text Info */}
            <div className="profile-text">
              <h1 className="profile-name">{userData.name}</h1>
              <p className="profile-subtext">{userData.grade} • {userData.email}</p>
            </div>

            {/* Action Buttons */}
            <div className="profile-buttons">
              <button className="btn-edit">
                <Edit size={16} /> Edit Profile
              </button>
              <button className="btn-signout" onClick={handleSignOut}>
                <LogOut size={16} /> Sign Out
              </button>
            </div>
          </div>
        </div>

        {/* --- Main Grid (Stats & Badges) --- */}
        <div className="profile-grid">
          
          {/* Left Column: Progress & Stats */}
          <div className="left-column">
            
            {/* Level Progress Card */}
            <div className="card level-card">
              <div className="card-header">
                <Trophy className="card-icon" color="#10b981" /> 
                <h3>Level Progress</h3>
              </div>
              
              <div className="level-info">
                <div className="level-box">1</div>
                <div className="progress-section">
                  <div className="progress-labels">
                    <span>Level 1</span>
                    <span>{userData.xp} / 500 XP</span>
                  </div>
                  <div className="progress-bar-bg">
                    <div className="progress-bar-fill" style={{width: `${(userData.xp/500)*100}%`}}></div>
                  </div>
                  <p className="xp-remaining">98 XP until Level 2</p>
                </div>
              </div>
            </div>

            {/* 4 Stats Cards Row */}
            <div className="stats-row-grid">
              <div className="stat-box">
                <Zap size={24} className="stat-icon" color="#10b981" />
                <h2>{userData.xp}</h2>
                <span>Total XP</span>
              </div>
              <div className="stat-box">
                <Flame size={24} className="stat-icon" color="#f97316" />
                <h2>{userData.streak}</h2>
                <span>Day Streak</span>
              </div>
              <div className="stat-box">
                <BookOpen size={24} className="stat-icon" color="#3b82f6" />
                <h2>{userData.quizzes}</h2>
                <span>Quizzes Done</span>
              </div>
              <div className="stat-box">
                <Award size={24} className="stat-icon" color="#10b981" />
                <h2>{userData.avgScore}</h2>
                <span>Avg Score</span>
              </div>
            </div>
          </div>

          {/* Right Column: Badges */}
          <div className="right-column">
            <div className="card badges-card">
              <div className="card-header">
                <Award className="card-icon" color="#10b981" /> 
                <h3>Badges</h3>
              </div>
              
              <div className="badges-empty-state">
                <div className="empty-badge-icon">
                  <Award size={48} color="#94a3b8" />
                </div>
                <p>Complete quizzes to earn badges!</p>
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
};

export default Profile;
